INSERT INTO journal(acteur, changement, motif) VALUES
('sas','Routage « extraction » basculé de deepseek-v4-flash vers upstage/solar-pro4',
 'Promu par le sas sur mesure : 88/100 contre 69 pour le titulaire, sur 4 passages de la batterie de 8 tâches figées, pour 65 % de moins. Seul l''Analyste est concerné — il décortique les devis clients, ce que la batterie mesure exactement. Le routage « redaction » du Héraut n''est PAS modifié : la batterie ne teste pas la rédaction persuasive en français, promouvoir sur cette base serait un abus de la mesure.'),
('metrologue','Batterie de 8 tâches figées créée, notation 100 % déterministe',
 'Aucun modèle juge : chaque tâche se vérifie par du code. Elle débloque les candidats que le sas refusait de trancher et fournit le premier point de la courbe de prix vendable au client. Constat notable : notre modèle d''extraction échouait à classer un courriel en un mot et à respecter une limite de 20 mots.');
